/* Shared interface pieces: one behaviour for every popup, a card picker instead of dropdowns, the resource bar,
 * and the Home desk. Loaded after game.js and act3.js. */

/* ---------- Popups ---------- */
/** Every .decision-modal gets the same behaviour: a close button, Escape, backdrop click and focus handling.
 * Closing uses the popup's own close button when it has one, so its logic (such as saving) still runs; a popup
 * without one, like an ending, is a choice the player must make. */
function enhanceModal(modal){
 if(modal.dataset.enhanced)return;modal.dataset.enhanced="1";
 const box=modal.querySelector(".decision-box");if(!box)return;
 modal.setAttribute("role",modal.getAttribute("role")||"dialog");modal.setAttribute("aria-modal","true");
 const heading=box.querySelector("h2");if(heading){heading.id||=`modal-title-${Date.now()}`;modal.setAttribute("aria-labelledby",heading.id);}
 const own=box.querySelector(".modal-close");const close=()=>own?own.click():null;
 if(own){const x=document.createElement("button");x.type="button";x.className="modal-x";x.setAttribute("aria-label","Close");x.textContent="✕";x.onclick=close;box.prepend(x);}
 modal.addEventListener("click",e=>{if(e.target===modal)close();});
 modal.addEventListener("keydown",e=>{
  if(e.key==="Escape"){e.preventDefault();close();}
  if(e.key==="Tab"){const f=[...box.querySelectorAll("button:not(:disabled),input,select,a[href]")];if(!f.length)return;const first=f[0],last=f[f.length-1];
   if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
 });
 const opener=document.activeElement;
 new MutationObserver((_,obs)=>{if(!modal.isConnected){obs.disconnect();if(opener&&opener.isConnected)opener.focus();}}).observe(document.body,{childList:true});
 (box.querySelector("input:not([type=radio]),.choice,.picker-option,button:not(.modal-x)")||box).focus?.();
}
if(typeof MutationObserver!=="undefined"&&typeof document!=="undefined"&&document.body){
 new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)if(n.classList?.contains("decision-modal"))enhanceModal(n);}).observe(document.body,{childList:true});
}

/* ---------- Picker ---------- */
/** A searchable grid of cards: the replacement for every dropdown. */
function openPicker({title,kicker="CHOOSE",intro="",options,current,onPick,search=options.length>8}){
 const modal=document.createElement("div");modal.className="decision-modal picker-modal";
 const card=o=>`<button type="button" class="picker-option ${o.value===current?"selected":""}" data-value="${safe(o.value)}" ${o.disabled?"disabled":""} data-search="${safe((o.label+" "+(o.meta||"")).toLowerCase())}"><strong>${safe(o.label)}</strong>${o.meta?`<small>${safe(o.meta)}</small>`:""}${o.detail?`<span>${safe(o.detail)}</span>`:""}${o.value===current?`<em>Current</em>`:""}</button>`;
 modal.innerHTML=`<div class="decision-box picker-box"><small>${safe(kicker)}</small><h2>${safe(title)}</h2>${intro?`<p>${safe(intro)}</p>`:""}${search?`<input class="picker-search" type="search" placeholder="Search…" aria-label="Search options" />`:""}<div class="picker-grid">${options.map(card).join("")}</div><button type="button" class="modal-close">Cancel</button></div>`;
 document.body.appendChild(modal);
 modal.querySelector(".modal-close").onclick=()=>modal.remove();
 modal.querySelectorAll(".picker-option").forEach(b=>b.onclick=()=>{modal.remove();onPick(b.dataset.value);});
 const input=modal.querySelector(".picker-search");
 if(input){input.oninput=()=>{const q=input.value.trim().toLowerCase();modal.querySelectorAll(".picker-option").forEach(b=>b.hidden=!!q&&!b.dataset.search.includes(q));};input.focus();}
 return modal;
}
/** The pickers the game offers, keyed by what they choose. Each returns picker options from the current state. */
const PICKERS={
 state:{title:"Choose a state or union territory",options:()=>Object.entries(SEAT_COUNTS).sort((a,b)=>b[1]-a[1]).map(([n,seats])=>{const p=state.org.presence[n]||0,t=presenceTier(p);return {value:n,label:n,meta:`${seats} Lok Sabha seat${seats===1?"":"s"} · presence ${p}/100 · ${t[1]}`};})},
 segment:{title:"Choose the audience",options:()=>GameEngine.api().demographicsView(state.world).map(g=>({value:g.key,label:SEGMENT_LABELS[g.key],meta:`${Math.round(g.weight*100)}% of voters · opinion ${g.value}/100`}))},
 bloc:{title:"Choose a partner",options:()=>FOREIGN_BLOCS.map(b=>({value:b.id,label:b.label,meta:`Relations ${state.foreignRelations[b.id]}/100`}))},
 rti:{title:"Choose what to ask for",options:()=>RTI_TOPICS.map(t=>({value:t.id,label:t.title,meta:t.office,detail:t.question,disabled:state.rtiRequests.some(r=>r.topic===t.id&&["filed","appealed"].includes(r.status))}))}
};
const PICK_LABELS={targetState:v=>`${v} · ${SEAT_COUNTS[v]} seats`,targetSegment:v=>SEGMENT_LABELS[v],targetBloc:v=>FOREIGN_BLOCS.find(b=>b.id===v)?.label,rtiTopic:v=>RTI_TOPICS.find(t=>t.id===v)?.title};
/** A button that shows the current choice and opens its picker. */
function pickerButton(kind,key,label){ensureState();const value=state[key];return `<span class="picker-field"><small>${safe(label)}</small><button type="button" class="picker-btn" data-pick="${kind}" data-key="${key}">${safe(PICK_LABELS[key]?.(value)??value??"Choose")}<b aria-hidden="true">▾</b></button></span>`;}
function pickAction(kind,key){const def=PICKERS[kind];if(!def)throw Error("Unknown choice.");openPicker({title:def.title,options:def.options(),current:state[key],onPick:v=>{state[key]=v;save();renderPage();}});}

/* ---------- Segmented choices (small number ranges) ---------- */
function segmented(key,label,values,suffix=""){const current=key.split(".").reduce((o,k)=>o?.[k],state);return `<div class="segmented" role="group" aria-label="${safe(label)}"><small>${safe(label)}</small><div>${values.map(v=>`<button type="button" data-set="${key}" data-value="${v}" aria-pressed="${current===v}" class="${current===v?"on":""}">${v}${suffix}</button>`).join("")}</div></div>`;}
function setAction(key,value){const parts=key.split("."),last=parts.pop(),target=parts.reduce((o,k)=>o[k],state);target[last]=Number(value);save();renderPage();}

/* ---------- Resource bar ---------- */
/** A game's resource strip: an icon and a number each, with the meaning on hover. Warnings pulse red. */
function hudHTML(){if(!state.player)return "";const o=state.org,p=state.player;
 const item=(icon,value,title,{warn,meter}={})=>`<span class="hud-chip ${warn?"warn":""}" title="${safe(title)}" aria-label="${safe(title)}: ${safe(String(value))}"><b aria-hidden="true">${icon}</b>${value}${meter!==undefined?`<i style="--v:${Math.max(0,Math.min(100,meter))}%"></i>`:""}</span>`;
 return [item("₹",money(o.funds),`Movement funds · monthly costs ₹${money(monthlyCosts())}`,{warn:o.funds<monthlyCosts()}),item("✊",o.volunteers.toLocaleString("en-IN"),"Volunteers"),item("◔",state.support+"%","Public support"),item("★",o.credibility,"Credibility (0–100)"),
  item("⚡",Math.round(p.energy),p.energy<25?"Your energy is dangerously low: rest":"Your energy",{warn:p.energy<25,meter:p.energy}),o.legal>0||o.legal>=40?item("⚖",o.legal,"Legal pressure · at 100 you are arrested",{warn:o.legal>=40}):"",
  (state.outrage||0)>0?item("🔥",Math.round(state.outrage),"Public outrage · channel it before it turns to unrest",{warn:state.outrage>=85}):"",state.phase==="government"?item("❖",prideIndex(),"India's pride index"):""].join("");}

/* ---------- Asking before acting ---------- */
/** What each consequential action is, what it costs and what it is likely to do. Unlisted actions still get a
 * dialog built from the button's own words. */
const ACT_INFO={
 fundraise:{title:"Run a small-donor drive",text:"Call and message supporters for small, disclosed contributions. Donors tire of repeated appeals.",effect:()=>({energy:-4})},
 rest:{title:"Take a day to rest",text:"Recover energy. The news cycle cools while you are away.",effect:()=>({energy:22,stress:-10,media:-2})},
 "advance-week":{title:"Advance the campaign by one week",text:()=>`Your routine will run for seven days: ${state.routine?.fundraise||0} donor drive${state.routine?.fundraise===1?"":"s"}, ${state.routine?.rest||0} rest day${state.routine?.rest===1?"":"s"}${state.phase!=="movement"?`, and ${state.routine?.tours||0} campaign tour${state.routine?.tours===1?"":"s"}`:""}. The clock stops if a decision needs you.`,effect:()=>null},
 "advance-month":{title:"Advance the campaign by four weeks",text:()=>`Your routine will run for 28 days. The clock stops at any decision, dispatch, crisis or campaign event that needs your response.`,effect:()=>null},
 recruit:{title:"Recruit volunteers",text:"Local outreach to bring new people in.",effect:()=>({funds:-3000,energy:-5})},
 "state-visit":{title:()=>`Visit ${state.targetState}`,text:"Meet local organisers and build field presence.",effect:()=>({funds:-20000,energy:-10,volunteers:24,support:1})},
 briefing:{title:"Hold an evidence briefing",text:"A carefully checked public update.",effect:()=>({funds:-5000,credibility:2,media:2,energy:-5})},
 interview:{title:"Give a national interview",text:"A big audience. If you are stressed, it can go badly.",effect:()=>({energy:-12,media:4})},
 "hidden-donation":{title:"Accept ₹40,000 from an undisclosed source",text:"It solves today's cash problem. It is also a secret that can surface at the worst moment, and it grows riskier the more attention you attract.",effect:()=>({funds:40000,secret:1}),danger:true},
 "found-party":{title:"Found the political party",text:"There is no going back to being a pressure group. Elections, candidates and a manifesto follow.",effect:()=>({funds:-100000,media:8}),danger:true},
 "switch-route":{title:"Turn toward electoral politics",text:"The civic pressure group will work toward founding a party. A party cannot return to the civic route.",danger:true},
 campaign:{title:()=>`Campaign tour in ${state.targetState}`,text:"Rallies and meetings that raise campaign preparation and local presence.",effect:()=>({funds:-25000,energy:-8,support:1})},
 election:{title:"Contest the general election",text:"All 543 seats. Your preparation, presence and candidates are what they are now.",effect:()=>({funds:-50000}),danger:true},
 "crisis-pr":{title:"Hire crisis PR",text:"Professionals cool a bad news cycle.",effect:()=>({funds:-15000,media:-15,legal:-10})},
 "pr-retainer":{title:"Sign a PR retainer",text:"₹8,000 every month from now on, for steadier credibility.",effect:()=>({funds:-20000})},
 services:{title:"Fund public services",text:"Visible delivery for ordinary people.",effect:()=>({funds:-40000,support:3,credibility:1,energy:-8})},
 thread:{title:"Publish an investigative thread",text:"Slow, sourced and credible.",effect:()=>({funds:-4000,energy:-10,credibility:4,media:5})},
 meme:{title:"Push fast content",text:"Wide reach. Sloppy if you are stressed.",effect:()=>({funds:-1500,media:6,energy:-3})}
};
/** Action types that change the world and so ask first; navigation, pickers and settings never do. */
const ASK_FIRST=new Set(["act","people","network","rti","suit","electoral","campaign","bill","outrage","project","civic","jantar","audit","rival","signal"]);
const NEVER_ASK_ACTS=new Set(["toggle-confirm","historical-scene","advance-chapter","handoff","open-crisis","wait-dispatch","decision","campaign-day","negotiate","export","import"]);
function needsConfirmation(type,p){if(!ASK_FIRST.has(type))return false;if(type==="act"&&NEVER_ASK_ACTS.has(p.act))return false;if(type==="people"&&p.action==="interview")return false;if(type==="audit"&&p.action==="response"||type==="rival"&&p.action==="response")return false;return true;}
function confirmAction(type,p,run){
 const info=type==="act"?ACT_INFO[p.act]:null;
 const title=(typeof info?.title==="function"?info.title():info?.title)||String(p.label||"Are you sure?").replace(/\s*·\s*/g," · ").trim();
 const text=(typeof info?.text==="function"?info.text():info?.text)||"This takes your day and changes what happens next.";
 const effect=info?.effect?.();const danger=info?.danger||/let go|release|appeal|found|accept undisclosed|inflammatory/i.test(p.label||"");
 const modal=document.createElement("div");modal.className=`decision-modal confirm-modal ${danger?"danger":""}`;
 modal.innerHTML=`<div class="decision-box confirm-box"><small>${danger?"THIS CANNOT EASILY BE UNDONE":"YOUR DECISION"}</small><h2>${safe(title)}</h2><p>${safe(text)}</p>${effect?`<div class="confirm-effects"><small>What it does</small>${effectChips(effect)}</div>`:""}<div class="confirm-actions"><button type="button" class="dispatch-action confirm-yes">${danger?"Yes, do it":"Do it"}</button><button type="button" class="modal-close">Not now</button></div></div>`;
 document.body.appendChild(modal);
 modal.querySelector(".modal-close").onclick=()=>modal.remove();
 modal.querySelector(".confirm-yes").onclick=()=>{modal.remove();try{run();}catch(e){toast(e.message);}};
 setTimeout(()=>modal.querySelector(".confirm-yes").focus(),0);
}
function renderHud(){const av=document.querySelector("#avatar-mini");if(av&&state.player&&!av.querySelector("svg"))av.innerHTML=portrait(state.player.name,{mood:"high"});const el=document.querySelector("#hud");if(el)el.innerHTML=hudHTML();}

/* ---------- Portraits ---------- */
/** A flat illustrated portrait drawn from the name, so the same person always looks the same. Expression follows
 * mood; "villain" gives the network's members a darker dossier look. Nothing about the portrait is inferred from
 * the name's meaning: every feature is an independent pick from a hash. */
const SKIN=["#7a4a2a","#8d5524","#a86b3c","#c68642","#d9a066","#e0ac69"];
const HAIR=["#1b1b1b","#241a14","#3b2a20","#2e2e2e","#4a3526","#6b6b6b"];
const BACKDROP=["#3b4a5a","#4a3b5a","#5a4a3b","#3b5a4a","#5a3b44","#44505a","#58503a"];
const SHIRT=["#b8463f","#3f6fb8","#3f9a6f","#c49a3f","#7a4fb0","#d0cabf","#2f3a45"];
function portrait(name,{mood="steady"}={}){
 let h=2166136261;for(const ch of String(name)){h^=ch.charCodeAt(0);h=Math.imul(h,16777619);}h>>>=0;
 const pick=(arr,shift)=>arr[(h>>>shift)%arr.length],bit=shift=>((h>>>shift)&1)===1;
 const villain=mood==="villain",skin=pick(SKIN,0),hair=pick(HAIR,3),bg=villain?"#241d20":pick(BACKDROP,6),shirt=villain?"#15171a":pick(SHIRT,9);
 const style=(h>>>12)%5,glasses=villain?bit(20):(h>>>15)%4===0,moustache=(h>>>17)%3===0;
 const hairBack=style===1?`<path d="M17 30c0-12 7-19 15-19s15 7 15 19v14H17z" fill="${hair}"/>`:"";
 const hairTop=[`<path d="M19 27c0-9 6-14 13-14s13 5 13 14c-3-4-8-6-13-6s-10 2-13 6z" fill="${hair}"/>`,
  `<path d="M19 28c0-10 6-15 13-15s13 5 13 15c-2-5-7-8-13-8s-11 3-13 8z" fill="${hair}"/>`,
  `<circle cx="32" cy="11" r="5" fill="${hair}"/><path d="M19 27c0-9 6-14 13-14s13 5 13 14c-3-5-8-6-13-6s-10 1-13 6z" fill="${hair}"/>`,
  `<path d="M19 28c1-10 7-15 14-15 6 0 12 4 12 12-5-2-9-6-12-9-2 5-7 9-14 12z" fill="${hair}"/>`,
  `<path d="M19 27c0-3 1-5 2-6v8zM45 27c0-3-1-5-2-6v8z" fill="${hair}"/>`][style];
 const eyes=mood==="rest"?`<path d="M26 30q2 2 4 0M34 30q2 2 4 0" stroke="#1b1b1b" stroke-width="1.6" fill="none" stroke-linecap="round"/>`:`<circle cx="28" cy="30" r="1.7" fill="#1b1b1b"/><circle cx="36" cy="30" r="1.7" fill="#1b1b1b"/>`;
 const brows=villain||mood==="low"?`<path d="M25 26l5 1.5M39 26l-5 1.5" stroke="${hair}" stroke-width="1.6" stroke-linecap="round"/>`:`<path d="M25 26.5q2.5-1.5 5 0M34 26.5q2.5-1.5 5 0" stroke="${hair}" stroke-width="1.6" fill="none" stroke-linecap="round"/>`;
 const mouth={high:`<path d="M28 37q4 4 8 0" stroke="#5a2a22" stroke-width="1.8" fill="none" stroke-linecap="round"/>`,low:`<path d="M28 39q4-3 8 0" stroke="#5a2a22" stroke-width="1.8" fill="none" stroke-linecap="round"/>`,villain:`<path d="M28 38q5 1.5 8-1.5" stroke="#3a1a16" stroke-width="1.8" fill="none" stroke-linecap="round"/>`}[mood]||`<path d="M29 38h6" stroke="#5a2a22" stroke-width="1.8" stroke-linecap="round"/>`;
 return `<svg class="portrait-svg" viewBox="0 0 64 64" role="img" aria-label="${safe(name)}"><rect width="64" height="64" fill="${bg}"/>${hairBack}<path d="M14 64c1-10 8-15 18-15s17 5 18 15z" fill="${shirt}"/><rect x="28" y="40" width="8" height="8" rx="3" fill="${skin}"/><ellipse cx="32" cy="30" rx="12" ry="14" fill="${skin}"/>${hairTop}${brows}${eyes}${glasses?`<g fill="none" stroke="${villain?"#c9b27a":"#1b1b1b"}" stroke-width="1.4"><circle cx="28" cy="30" r="3.6"/><circle cx="36" cy="30" r="3.6"/><path d="M31.6 30h.8"/></g>`:""}${moustache?`<path d="M28 35.5q4-2 8 0q-4 1.5-8 0z" fill="${hair}"/>`:""}${mouth}</svg>`;}

/* ---------- Home: the desk ---------- */
const LONG_DATE=new Intl.DateTimeFormat("en-GB",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"});
/** Where the player is in the whole story, from the reported timeline to the endgame. */
function journeyHTML(){const steps=["Act 1","Handoff","Chapter 1","Chapter 2","Chapter 3","Chapter 4","Endgame"];
 const at=state.historicalRoleplay&&state.date<=timelineCutoff()?0:state.historicalRoleplay&&!state.handoff?1:!state.historicalRoleplay?2+Math.min(4,state.careerChapter||0):2+Math.min(4,state.careerChapter||0);
 return `<ol class="journey" aria-label="Your story so far">${steps.map((s,i)=>`<li class="${i<at?"done":i===at?"now":""}"><i aria-hidden="true"></i><span>${s}</span></li>`).join("")}</ol>`;}
function campaignPulseHTML(){const dispatch=state.pendingScenes?.length?"Historical dispatch waiting":state.pendingCrisis?"National crisis waiting":state.pendingTip?"Anonymous tip received":openInjustices().length?`${openInjustices().length} field case${openInjustices().length===1?"":"s"} open`:"Field desk quiet";const operation=state.projects.find(x=>x.status==="active");const signal=(state.fieldSignals||[]).find(x=>!x.used);return `<section class="campaign-pulse" aria-label="Campaign pulse"><div class="pulse-live"><i></i><span>LIVE DESK</span><strong>${safe(dispatch)}</strong></div><div><small>OPERATIONS</small><strong>${operation?`${safe(operation.name)} · ${operation.remaining} day${operation.remaining===1?"":"s"}`:"No active operation"}</strong></div><div><small>FIELD SIGNAL</small><strong>${signal?`${safe(signal.state)} · ${safe(signal.title)}`:"Awaiting weekly leads"}</strong></div></section>`;}
function operationReviewHTML(){const review=(state.operationFollowups||[]).find(x=>x.dueDay<=state.day);return review?`<section class="operation-review"><div><small>OPERATION COMPLETE · REVIEW REQUIRED</small><h2>${safe(review.name)}</h2><p>The ${safe(review.approach||"field")} plan has concluded. Decide what happens to the work next.</p></div><button type="button" data-review-operation="${safe(review.id)}">OPEN FIELD REPORT →</button></section>`:"";}
/** The whole desk is meant to fit one screen: details live in dialogs and collapsible sections. */
function deskHTML(){ensureState();const custom=!(state.historicalRoleplay&&state.flags.firstResponse);
 const alert=historyAlertHTML(),boundary=alert.includes("history-boundary");
 return `<section class="page desk">
  <header class="desk-head"><div><p class="desk-eyebrow">${safe(state.org.name)} · ${safe(state.phase)}</p><h1>Command desk</h1></div>
   <div class="desk-day" aria-label="Day ${state.day}"><b>${state.day}</b><span>Day<br>${LONG_DATE.format(new Date(state.date+"T00:00:00Z"))}</span></div></header>
  ${journeyHTML()}${campaignPulseHTML()}${operationReviewHTML()}
  ${boundary?"":alert}
  <div class="desk-grid"><div class="desk-main">${custom?commandDispatchHTML():careerDispatchHTML()}${deskFeedHTML()}${jantarHTML()}</div>
  <aside class="desk-side">${daysCardHTML()}${teamMiniHTML()}</aside></div></section>`;}
/** Days left as a ring: full when a case arrives, empty on its last day. */
function countdownRing(left,total){const r=15,c=2*Math.PI*r,frac=Math.max(0,Math.min(1,left/Math.max(1,total)));
 return `<span class="ring ${left<=1?"urgent":""}"><svg viewBox="0 0 36 36" aria-hidden="true"><circle cx="18" cy="18" r="${r}" class="ring-track"/><circle cx="18" cy="18" r="${r}" class="ring-fill" stroke-dasharray="${(c*frac).toFixed(1)} ${c.toFixed(1)}"/></svg><b>${Math.max(0,left)}</b><small>${left===1?"day":"days"}</small></span>`;}
/** The feed as a list of case rows; each opens its full case file. Outcomes and the outrage controls stay compact. */
function deskFeedHTML(){ensureState();if(state.date<"2026-05-20"||!state.flags.firstResponse)return "";
 const open=openInjustices(),recent=state.injustices.filter(x=>x.status!=="open").slice(0,5),o=Math.round(state.outrage),legal=state.org.legal;
 const rows=open.map(x=>{const t=INJUSTICE_CASES.find(c=>c.id===x.id),bg=BEFORE_THE_MOVEMENT.find(b=>b.id===t.pattern);
  return `<li><button type="button" class="case-row" data-case-open="${safe(x.uid)}">${countdownRing(daysBetween(state.date,x.dueOn),t.days)}<span class="case-text"><strong>${safe(t.title)}</strong><small>${safe(x.district)} · ${safe(bg.topic)} · fictional case</small></span><span class="case-go">Open case file ›</span></button></li>`;}).join("");
 return `<section class="desk-card feed"><header class="card-head"><h2>Injustice feed</h2><span class="live">Live · ${open.length} open</span></header>
  ${legal>=40?`<div class="legal-line"><span><b>Legal pressure ${legal}/100.</b> At 100 you are arrested.</span><button type="button" data-outrage="counsel">Retain senior counsel · ₹30,000</button></div>`:""}
  <div class="outrage-line"><span class="outrage-label">Public outrage</span><span class="outrage-bar"><i style="width:${o}%"></i></span><b>${o}</b><button type="button" data-outrage="protest" ${o<30?"disabled title=\"Outrage must reach 30\"":""}>Protest</button><button type="button" data-outrage="report" ${o<20?"disabled title=\"Outrage must reach 20\"":""}>Report</button></div>
  ${rows?`<ul class="case-list">${rows}</ul>`:`<p class="card-hint">No open cases today. They will come.</p>`}
  ${recent.length?`<details class="recent"><summary>Recent outcomes <span>${recent.length}</span></summary><ul>${recent.map(x=>`<li class="${x.status}"><small>${safe(x.closedOn)} · ${x.status==="answered"?"Answered":"No one came"} · ${safe(x.district)}</small><strong>${safe(INJUSTICE_CASES.find(c=>c.id===x.id).title)}</strong><p>${safe(x.outcome)}</p></li>`).join("")}</ul></details>`:""}</section>`;}
/** A case file: the full story, the documented pattern behind it, and the responses with their consequences. */
function openCase(uid){ensureState();const x=state.injustices.find(v=>v.uid===uid);if(!x||x.status!=="open")return toast("This case is closed.");
 const t=INJUSTICE_CASES.find(c=>c.id===x.id),bg=BEFORE_THE_MOVEMENT.find(b=>b.id===t.pattern),left=daysBetween(state.date,x.dueOn);
 const modal=document.createElement("div");modal.className="decision-modal case-modal";
 modal.innerHTML=`<div class="decision-box case-box"><div class="case-head">${countdownRing(left,t.days)}<div><small>CASE FILE · ${safe(x.district.toUpperCase())} · FICTIONAL</small><h2>${safe(t.title)}</h2></div></div><p class="case-body">${safe(fillDistrict(t.body,x.district))}</p>
  <details class="why"><summary>Why this happens</summary><p>${safe(bg.record)} <a href="${safe(bg.url)}" target="_blank" rel="noopener noreferrer">${safe(bg.source)} ↗</a></p></details>
  <div class="choices">${t.responses.map((r,i)=>`<button type="button" class="choice" data-respond="${i}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${safe(r.label)}</strong><small>${safe(r.detail)}</small>${effectChips(r.effect)}${r.evidence&&t.lead?`<span class="effect-chips"><i class="up">Evidence +${r.evidence}</i></span>`:""}</span></button>`).join("")}</div>
  <p class="case-ignore">If no one comes: ${safe(fillDistrict(t.ignored.text,x.district))}</p><button type="button" class="modal-close">Decide later</button></div>`;
 document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();
 modal.querySelectorAll("[data-respond]").forEach(b=>b.onclick=()=>{try{respondInjustice(uid,b.dataset.respond);modal.remove();}catch(e){toast(e.message);}});}
function segmentRow(key,label,values){const current=key.split(".").reduce((o,k)=>o?.[k],state);return `<div class="setting-row"><span>${safe(label)}</span><div class="seg" role="group" aria-label="${safe(label)}">${values.map(v=>`<button type="button" data-set="${key}" data-value="${v}" aria-pressed="${current===v}" class="${current===v?"on":""}">${v}</button>`).join("")}</div></div>`;}
/** Your days: time controls always visible; the routine settings fold away once chosen. */
function daysCardHTML(){const blocked=routineBlocked(),started=!!state.flags.firstResponse,r=state.routine;
 const quick=(act,icon,title,detail,extra="")=>`<button type="button" class="quick" data-act="${act}" ${extra}><span class="quick-icon" aria-hidden="true">${icon}</span><span class="quick-text"><strong>${title}</strong><small>${detail}</small></span><span class="quick-go" aria-hidden="true">›</span></button>`;
 const summary=`${r.fundraise} drive${r.fundraise===1?"":"s"} · ${r.rest} rest${state.phase!=="movement"?` · ${r.tours} tour${r.tours===1?"":"s"}`:""}`;
 return `<section class="desk-card days"><header class="card-head"><h2>Your days</h2><span>Day ${state.day}</span></header>
  ${started?`<div class="btn-pair"><button type="button" class="btn primary" data-act="advance-week" ${blocked?"disabled":""}>Advance a week</button><button type="button" class="btn ghost" data-act="advance-month" ${blocked?"disabled":""}>A month</button></div>
  <details class="routine-details" ${state.ui?.routineOpen?"open":""}><summary>Weekly routine <span>${summary}</span></summary><div class="routine-rows">${segmentRow("routine.fundraise","Donor drives a week",[0,1,2,3])}${segmentRow("routine.rest","Rest days a week",[0,1,2])}${state.phase!=="movement"?segmentRow("routine.tours","Campaign tours a week",[0,1,2]):""}</div><p class="card-hint">Other days go to movement work. You rest when exhausted; anything that needs you stops the clock.</p></details>`:""}
  <div class="quick-list">
   ${!state.flags.firstResponse||!state.historicalRoleplay?quick("decision","⚡","Today's decision","A major choice is waiting"):""}
   ${state.date>="2026-06-06"&&state.date<="2026-07-25"?quick("campaign-day","◎","Run a protest day","Choose a field focus"):""}
   ${state.date>="2026-07-20"&&state.date<="2026-07-25"?quick("negotiate","◇","Set the negotiating position","Pick a demand"):""}
   ${quick("rest","☕","Rest today","Recover energy")}${quick("fundraise","₹","Donor drive today","Small, disclosed contributions")}
   ${quick("wait-dispatch","◷","Wait for the next dispatch",state.date>timelineCutoff()?"Up to 30 days":"Jump to the next dated event",!started||state.pendingScenes.length||state.pendingCrisis?"disabled":"")}
  </div></section>`;}
function teamMiniHTML(){const people=team().filter(x=>x.status!=="available"),shown=people.slice(0,5);
 return `<section class="desk-card team-card"><header class="card-head"><h2>Your team</h2><span>${people.length} with you</span></header>
  ${people.length?`<ul class="team-rows">${shown.map(x=>{const [mood,label]=moodOf(x);return `<li><button type="button" class="team-row" data-talk="${safe(x.id)}"><span class="avatar ${mood}" aria-hidden="true">${portrait(x.name,{mood})}</span><span class="team-text"><strong>${safe(x.name)}</strong><small>${safe(x.request?`Waiting on you: ${x.request.type}`:x.signals[0]||x.role)}</small></span><span class="mood ${mood}">${label}</span></button></li>`;}).join("")}</ul>`:`<p class="card-hint">No one has joined yet.</p>`}
  <button type="button" class="btn ghost wide" data-go="people">${people.length>shown.length?`See all ${people.length} on the People desk`:"Open the People desk"}</button></section>`;}

/* ---------- People as characters ---------- */
/** A colleague's mood, read from what they show: never from their private numbers. */
function moodOf(x){const s=x.signals.join(" ").toLowerCase();if(/exhausted|serious strain|morale has fallen|resentment|strained|unpaid|bruised/.test(s))return ["low","Struggling"];if(/energised|fiercely loyal|close friend|strongly trusts|speaks warmly/.test(s))return ["high","Fired up"];if(x.status==="on_leave")return ["rest","On leave"];return ["steady","Steady"];}
function characterCardHTML(x){const [mood,label]=moodOf(x),joined=x.status!=="available";
 return `<article class="character ${mood} ${x.status}"><div class="character-face" aria-hidden="true">${portrait(x.name,{mood})}<i></i></div><div class="character-body"><strong>${safe(x.name)}</strong><small>${safe(joined?x.role:`Could be your ${x.suggestedRoleTitle}`)} · ${STAFF_STATUS[x.status]}</small><p class="character-line">${joined?safe(x.request?`“${x.request.detail}”`:x.signals[0]||""):safe(x.background)}</p>${joined?`<span class="mood-tag">${label}</span>`:""}</div><button type="button" class="talk-btn" data-talk="${safe(x.id)}">${joined?"Talk":"Approach"}</button></article>`;}
/** Talking to someone: their story, what they remember, and what you can do, each option with its meaning. */
function openTalk(id){ensureState();const x=team().find(v=>v.id===id);if(!x)return toast("They are not available.");const w=state.world,joined=x.status!=="available"&&x.status!=="former";
 const opt=(action,title,detail,extra={})=>({action,title,detail,...extra});const options=[];const first=x.name.split(" ")[0];
 if(!joined){options.push(opt("volunteer","Ask them to join as a volunteer","Unpaid. They start now, and they will remember that you asked."),opt("hire",`Offer a paid role · ₹${money(STAFF_SALARY)} a month`,"A salary you must meet every month. Missed pay lands differently on each person."));}
 else{
  if(x.request)options.push(opt("grant",x.request.type==="raise"?"Agree to the raise":"Agree to their request","They will remember you kept faith with them."),opt("deny","Say no, for now",`${first} will remember the refusal. Proud, ambitious people remember it longer.`,{danger:true}));
  if(x.status!=="on_leave")options.push(opt("time-off","Send them home for three days","They recover and come back steadier. The work waits."));
  const last=w.flags[`defended_${id}`];options.push(opt("defend","Defend them in public","A public show of trust they will remember for years. Costs you 4 energy.",{disabled:last&&daysBetween(last,state.date)<14?"You defended them recently.":""}));
  if(x.founding)options.push(opt("recognise","Honour them as a founding member","A moment they will carry for the rest of their career.",{disabled:w.flags[`recognised_${id}`]?"Already honoured.":""}));
  if(x.status==="volunteer")options.push(opt("hire",`Put them on the payroll · ₹${money(STAFF_SALARY)} a month`,"They have earned it; your monthly costs rise."));
  options.push(opt("release","Let them go",`${first} leaves the organisation. How they remember it depends on who they are.`,{danger:true}));
 }
 const [mood,label]=moodOf(x);
 const modal=document.createElement("div");modal.className="decision-modal talk-modal";
 modal.innerHTML=`<div class="decision-box talk-box"><div class="talk-head"><div class="character-face big ${mood}" aria-hidden="true">${portrait(x.name,{mood})}<i></i></div><div><small>${safe(joined?`${x.role} · ${label}`:`Could be your ${x.suggestedRoleTitle}`)}</small><h2>${safe(x.name)}</h2><p class="muted">${safe(x.background)}${x.homeState?` From ${safe(x.homeState)}.`:""}</p></div></div>`+
  (x.signals.length?`<div class="talk-read"><small>What you notice</small><ul>${x.signals.map(s=>`<li>${safe(s)}</li>`).join("")}</ul></div>`:"")+
  (x.memories.length?`<p class="staff-memory">They remember: ${x.memories.map(safe).join(" · ")}</p>`:"")+
  `<div class="choices">${options.map((o,i)=>`<button type="button" class="choice ${o.danger?"danger":""}" data-talk-action="${o.action}" ${o.disabled?`disabled title="${safe(o.disabled)}"`:""}><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${safe(o.title)}</strong><small>${safe(o.disabled||o.detail)}</small></span></button>`).join("")}</div><button type="button" class="modal-close">Leave it for now</button></div>`;
 document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();
 modal.querySelectorAll("[data-talk-action]").forEach(b=>b.onclick=()=>{modal.remove();GameEngine.dispatch("people",{action:b.dataset.talkAction,id});});
}
/** Meeting a candidate: what the interviews have shown so far, and the choice to hire. */
function openCandidate(id){ensureState();const c=GameEngine.api().recruitmentView(state.world).find(v=>v.id===id);if(!c)return toast("That candidate has moved on.");
 const modal=document.createElement("div");modal.className="decision-modal talk-modal";
 modal.innerHTML=`<div class="decision-box talk-box"><div class="talk-head"><div class="character-face big steady" aria-hidden="true">${portrait(c.name)}<i></i></div><div><small>Candidate · best fit ${safe(c.suggestedRoleTitle)} · interviewed ${c.interviewLevel} of 2 times</small><h2>${safe(c.name)}</h2><p class="muted">${safe(c.background)} ${c.age}, from ${safe(c.homeState)}.</p></div></div>`+
  `<div class="talk-read"><small>What you have seen so far</small><ul>${c.headline.map(h=>`<li>${safe(h)}</li>`).join("")}${Object.entries(c.estimatedSkills).map(([k,v])=>`<li>${safe(k)}: ${safe(v)}</li>`).join("")}${c.concerns.map(h=>`<li class="concern">${safe(h)}</li>`).join("")}</ul></div>`+
  `<div class="choices"><button type="button" class="choice" data-cand="interview" ${c.interviewLevel>=2?"disabled":""}><span class="choice-key">A</span><span><strong>Interview them${c.interviewLevel?" again":""}</strong><small>${c.interviewLevel>=2?"You have learned what interviews can show.":"Costs 6 energy. Narrows the estimate and may surface a concern."}</small></span></button><button type="button" class="choice" data-cand="hire-candidate"><span class="choice-key">B</span><span><strong>Hire them · ₹${money(STAFF_SALARY)} a month</strong><small>You are hiring what you have seen, not what is hidden.</small></span></button><button type="button" class="choice" data-cand="volunteer-candidate"><span class="choice-key">C</span><span><strong>Take them on as a volunteer</strong><small>No salary. Ambitious people may not stay unpaid for long.</small></span></button></div><button type="button" class="modal-close">Not yet</button></div>`;
 document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();
 modal.querySelectorAll("[data-cand]").forEach(b=>b.onclick=()=>{if(b.dataset.cand==="interview"){modal.remove();return openCandidateInterview(id);}modal.remove();GameEngine.dispatch("people",{action:b.dataset.cand,id});});
}
function openCandidateInterview(id){ensureState();const c=GameEngine.api().recruitmentView(state.world).find(v=>v.id===id);if(!c)return toast("That candidate has moved on.");const questions=[{id:"craft",title:"Ask them to solve a field problem",detail:"Tests judgement under limited time and money.",reply:"They map who should be listened to before proposing a solution."},{id:"pressure",title:"Ask about a difficult disagreement",detail:"Tests integrity and how they handle pressure.",reply:"They describe the trade-off, not a perfect answer — and explain who they would consult."},{id:"care",title:"Ask what support they need to do good work",detail:"Tests self-awareness and whether the role is sustainable.",reply:"They name boundaries, workload and what a responsible team would provide."}];const modal=document.createElement("div");modal.className="decision-modal talk-modal";modal.innerHTML=`<div class="decision-box talk-box"><small>INTERVIEW ROOM · ROUND ${c.interviewLevel+1} OF 2</small><h2>What do you need to learn from ${safe(c.name)}?</h2><p>Choose one meaningful question. An interview narrows the estimate; it does not reveal a whole person.</p><div class="choices">${questions.map((q,i)=>`<button class="choice" data-question="${q.id}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${q.title}</strong><small>${q.detail}</small></span></button>`).join("")}</div><button class="modal-close">Return to candidate</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>{modal.remove();openCandidate(id);};modal.querySelectorAll("[data-question]").forEach(b=>b.onclick=()=>{const q=questions.find(x=>x.id===b.dataset.question);modal.querySelector(".talk-box").innerHTML=`<small>INTERVIEW NOTE</small><h2>${safe(c.name)} answers</h2><p>${safe(q.reply)}</p><div class="talk-read"><small>What this question can show</small><p>${safe(q.detail)} The engine will update the information available to you; hidden traits remain hidden.</p></div><div class="choices"><button class="choice" data-complete-interview><span class="choice-key">✓</span><span><strong>Record interview · 6 energy</strong><small>Save the answer, update your estimate and return to the candidate card.</small></span></button></div><button class="modal-close">Return to candidate</button>`;modal.querySelector(".modal-close").onclick=()=>{modal.remove();openCandidate(id);};modal.querySelector("[data-complete-interview]").onclick=()=>{modal.remove();GameEngine.dispatch("people",{action:"interview",id});setTimeout(()=>openCandidate(id),0);};});}
function openOperationPlanner(id){const project=PROJECTS.find(x=>x.id===id);if(!project)return;const plans=[{id:"listen",title:"Listen first",detail:"Start with a small local briefing and adapt from what people say."},{id:"deliver",title:"Deliver visibly",detail:"Set a public, practical outcome and make the work easy to verify."},{id:"build",title:"Build local capacity",detail:"Put volunteers in charge of the work that continues after launch."}];const modal=document.createElement("div");modal.className="decision-modal";modal.innerHTML=`<div class="decision-box"><small>OPERATION PLANNER · STEP 1 OF 2</small><h2>${safe(project.name)}</h2><p>${safe(project.description)}</p><div class="talk-read"><small>COMMITMENT</small><p>₹${money(project.cost)} · ${project.days} day${project.days>1?"s":""} · ${project.energy} energy</p></div><h3>What should this operation optimise for?</h3><div class="choices">${plans.map((x,i)=>`<button class="choice" data-plan="${x.id}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${x.title}</strong><small>${x.detail}</small></span></button>`).join("")}</div><button class="modal-close">Back to board</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();modal.querySelectorAll("[data-plan]").forEach(b=>b.onclick=()=>{const plan=plans.find(x=>x.id===b.dataset.plan);modal.querySelector(".decision-box").innerHTML=`<small>OPERATION PLANNER · STEP 2 OF 2</small><h2>${safe(project.name)}</h2><div class="talk-read"><small>YOUR PLAN</small><p><strong>${safe(plan.title)}</strong> — ${safe(plan.detail)}</p></div><p>The same budget and time are committed; this records the leadership intent behind the operation.</p><div class="choices"><button class="choice" data-launch-plan><span class="choice-key">✓</span><span><strong>Launch operation</strong><small>Spend ₹${money(project.cost)} and begin the ${project.days}-day work.</small></span></button></div><button class="modal-close">Revise plan</button>`;modal.querySelector(".modal-close").onclick=()=>openOperationPlanner(id)&&modal.remove();modal.querySelector("[data-launch-plan]").onclick=()=>{state.operationPlans??=[];state.operationPlans.unshift({date:state.date,project:id,approach:plan.id});record("Operation plan",`${project.name}: ${plan.title}.`);modal.remove();GameEngine.dispatch("project",{id,approach:plan.id});};});}
function openMediaStudio(kind){const reel=kind==="interview"?null:REEL_TYPES.find(x=>`reel-${x.id}`===kind);if(kind!=="interview"&&!reel)return;const formats=kind==="interview"?[{id:"evidence",title:"Lead with verified facts",detail:"Precise, composed and harder to misrepresent."},{id:"human",title:"Lead with what people experience",detail:"Warm and direct; make the stakes understandable."},{id:"challenge",title:"Challenge the framing",detail:"Sharper and more memorable, with a risk of heat."}]:[{id:"evidence",title:"Evidence cut",detail:"Use a clear claim, source and practical next step."},{id:"human",title:"People-first cut",detail:"Let a fictionalised volunteer story carry the message."},{id:"trend",title:"Fast trend cut",detail:"Use the current visual language for reach, not depth."}];const modal=document.createElement("div");modal.className="decision-modal";const title=reel?reel.label:"National interview";modal.innerHTML=`<div class="decision-box"><small>${reel?"REEL STUDIO":"INTERVIEW GREEN ROOM"} · STEP 1 OF 3</small><h2>${safe(title)}</h2><p>${reel?safe(reel.flavor):"A simulated national broadcast. Decide how you will answer before the cameras roll."}</p><h3>Choose the editorial angle</h3><div class="choices">${formats.map((x,i)=>`<button class="choice" data-media-angle="${x.id}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${x.title}</strong><small>${x.detail}</small></span></button>`).join("")}</div><button class="modal-close">Leave studio</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();modal.querySelectorAll("[data-media-angle]").forEach(b=>b.onclick=()=>{const angle=formats.find(x=>x.id===b.dataset.mediaAngle);modal.querySelector(".decision-box").innerHTML=`<small>${reel?"REEL STUDIO":"INTERVIEW GREEN ROOM"} · STEP 2 OF 3</small><h2>Review the brief</h2><div class="talk-read"><small>${safe(angle.title)}</small><p>${safe(angle.detail)}</p></div><p>${reel?"Check that the first three seconds make a truthful promise. The edit stays within the campaign's stated message.":"The producer will press for a short answer. You can keep the answer on the chosen brief."}</p><div class="choices"><button class="choice" data-media-review><span class="choice-key">→</span><span><strong>Take it to final review</strong><small>No cost yet. You can still back out before publishing.</small></span></button></div><button class="modal-close">Change angle</button>`;modal.querySelector(".modal-close").onclick=()=>openMediaStudio(kind)&&modal.remove();modal.querySelector("[data-media-review]").onclick=()=>{modal.querySelector(".decision-box").innerHTML=`<small>${reel?"REEL STUDIO":"INTERVIEW GREEN ROOM"} · STEP 3 OF 3</small><h2>Ready to go live?</h2><p><strong>${safe(angle.title)}</strong> is locked. ${reel?`This uses ₹${money(reel.cost)} and ${reel.energy} energy.`:"This uses 12 energy and raises your national profile."}</p><div class="choices"><button class="choice" data-media-publish><span class="choice-key">✓</span><span><strong>${reel?"Publish reel":"Enter interview"}</strong><small>Commit this public message and advance the day.</small></span></button></div><button class="modal-close">Return to edit</button>`;modal.querySelector(".modal-close").onclick=()=>openMediaStudio(kind)&&modal.remove();modal.querySelector("[data-media-publish]").onclick=()=>{state.lastMediaPlan={date:state.date,kind:kind,angle:angle.id};if(angle.id==="evidence")applyEffect({credibility:1});if(angle.id==="human")applyEffect({recognition:1});if(angle.id==="trend"||angle.id==="challenge")applyEffect({media:1,credibility:-1});modal.remove();GameEngine.dispatch("act",{act:reel?kind:"interview"});};};});}

function openMediaActionRoom(kind){const configs={briefing:{title:"Evidence briefing",cost:"₹5,000 · 5 energy",brief:"A public update must be precise enough to survive scrutiny."},meme:{title:"Fast content",cost:"₹1,500 · 3 energy",brief:"A quick visual can travel far, but it needs a clear purpose."},thread:{title:"Investigative thread",cost:"₹4,000 · 10 energy",brief:"Turn verified reporting into a readable public record."},livestream:{title:"Livestream Q&A",cost:"15 energy",brief:"Unscripted questions reward preparation and expose fatigue."},"crisis-pr":{title:"Crisis PR response",cost:"₹15,000",brief:"The team must acknowledge the situation without concealing facts."},"pr-retainer":{title:"PR retainer",cost:"₹20,000 now · ₹8,000/month",brief:"A standing relationship changes how the campaign communicates over time."}};const config=configs[kind];if(!config)return;const routes=[{id:"facts",title:"Lead with the record",detail:"Make the claim, evidence and next step easy to check."},{id:"people",title:"Lead with lived impact",detail:"Keep the message grounded in what the work changes for people."},{id:"reach",title:"Lead with a clear hook",detail:"Make the first line memorable while keeping it truthful."}];const modal=document.createElement("div");modal.className="decision-modal";modal.innerHTML=`<div class="decision-box"><small>MEDIA DESK · STEP 1 OF 3</small><h2>${safe(config.title)}</h2><p>${safe(config.brief)}</p><h3>What should lead this message?</h3><div class="choices">${routes.map((r,i)=>`<button class="choice" data-media-route="${r.id}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${r.title}</strong><small>${r.detail}</small></span></button>`).join("")}</div><button class="modal-close">Leave desk</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();modal.querySelectorAll("[data-media-route]").forEach(button=>button.onclick=()=>{const route=routes.find(r=>r.id===button.dataset.mediaRoute);modal.querySelector(".decision-box").innerHTML=`<small>MEDIA DESK · STEP 2 OF 3</small><h2>Check the brief</h2><div class="talk-read"><small>${safe(route.title)}</small><p>${safe(route.detail)}</p></div><p>Cost if you proceed: <strong>${safe(config.cost)}</strong>. The message stays within the simulated campaign; no claim is invented here.</p><div class="choices"><button class="choice" data-media-check><span class="choice-key">→</span><span><strong>Send to final review</strong><small>Check the commitment before it becomes public.</small></span></button></div><button class="modal-close">Change approach</button>`;modal.querySelector(".modal-close").onclick=()=>openMediaActionRoom(kind)&&modal.remove();modal.querySelector("[data-media-check]").onclick=()=>{modal.querySelector(".decision-box").innerHTML=`<small>MEDIA DESK · STEP 3 OF 3</small><h2>Approve this action?</h2><p><strong>${safe(route.title)}</strong> is the lead. ${safe(config.cost)} will be committed when you approve.</p><div class="confirm-effects"><small>WHAT HAPPENS NEXT</small><p>The campaign records this editorial choice, carries out the action, and advances the day.</p></div><div class="confirm-actions"><button class="dispatch-action confirm-yes" data-media-approve>Approve and act</button><button class="modal-close">Return to edit</button></div></div>`;modal.querySelector(".modal-close").onclick=()=>openMediaActionRoom(kind)&&modal.remove();modal.querySelector("[data-media-approve]").onclick=()=>{state.lastMediaPlan={date:state.date,kind,angle:route.id};record("Media brief",`${config.title}: ${route.title}.`);modal.remove();GameEngine.dispatch("act",{act:kind});};};});}
function openOperationReview(id){const review=(state.operationFollowups||[]).find(x=>x.id===id);if(!review)return toast("That field report has already been filed.");const choices=[{id:"share",title:"Hold a public debrief",detail:"Give supporters a clear account of what was done.",effect:{media:2,credibility:1}},{id:"handover",title:"Hand it to local organisers",detail:"Keep the work useful after the campaign leaves.",effect:{volunteers:8,credibility:1}},{id:"audit",title:"Publish a lessons note",detail:"Record what worked and what still needs proof.",effect:{legal:-2,credibility:2}}];const modal=document.createElement("div");modal.className="decision-modal";modal.innerHTML=`<div class="decision-box"><small>OPERATION REPORT · COMPLETED</small><h2>${safe(review.name)}</h2><p>The ${safe(review.approach||"field")} approach has delivered its initial work. Your follow-up determines what the organisation learns from it.</p><div class="choices">${choices.map((c,i)=>`<button class="choice" data-operation-outcome="${c.id}"><span class="choice-key">${String.fromCharCode(65+i)}</span><span><strong>${c.title}</strong><small>${c.detail}</small>${effectChips(c.effect)}</span></button>`).join("")}</div><button class="modal-close">File later</button></div>`;document.body.appendChild(modal);modal.querySelector(".modal-close").onclick=()=>modal.remove();modal.querySelectorAll("[data-operation-outcome]").forEach(button=>button.onclick=()=>{const choice=choices.find(c=>c.id===button.dataset.operationOutcome);applyEffect(choice.effect);state.operationFollowups=state.operationFollowups.filter(x=>x.id!==id);record("Operation follow-up",`${review.name}: ${choice.title}.`);save();renderPage();modal.remove();toast("Field report filed.");});}
function showCampaignClock(report){if(typeof document==="undefined"||!document.body)return;const fmt=date=>new Date(date+"T00:00:00Z").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).toUpperCase();const headlines=(report.headlines||[]).slice(0,4);const motion=report.passed>1?"DAYS MOVE":"NEXT DAY";const summary=[report.drives?`${report.drives} donor drive${report.drives===1?"":"s"}`:"",report.rested?`${report.rested} recovery day${report.rested===1?"":"s"}`:"",report.tours?`${report.tours} field tour${report.tours===1?"":"s"}`:""].filter(Boolean).join(" · ")||"The campaign kept moving.";const modal=document.createElement("div");modal.className="decision-modal campaign-clock-modal";modal.innerHTML=`<div class="campaign-clock"><div class="clock-montage"><small>${motion}</small><strong>${fmt(report.start)}</strong><i aria-hidden="true">→</i><strong>${fmt(report.end)}</strong><span class="clock-days">+${report.passed} DAY${report.passed===1?"":"S"}</span></div><article class="field-edition"><div class="paper-masthead"><span>REPUBLIC 543</span><b>FIELD EDITION</b><span>${fmt(report.end)}</span></div><div class="paper-lead"><small>CAMPAIGN DESK</small><h2>${safe(report.reason||"The week closes. The next move is yours.")}</h2><p>${safe(summary)}${report.raised?` · ₹${money(report.raised)} raised from disclosed donors.`:""}</p></div><div class="paper-headlines">${headlines.map((h,i)=>`<div><b>${i===0?"LEAD":"BRIEF"}</b><strong>${safe(h.title)}</strong><span>${safe(h.detail)}</span></div>`).join("")||"<p>No field report was filed.</p>"}</div><button type="button" class="dispatch-action clock-continue">Read the field →</button></article></div>`;document.body.appendChild(modal);modal.querySelector(".clock-continue").onclick=()=>modal.remove();}
