function showCampaignClock(report){if(typeof document==="undefined"||!document.body||!document.createElement)return;const fmt=date=>new Date(date+"T00:00:00Z").toLocaleDateString("en-IN",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).toUpperCase(),headlines=(report.headlines||[]).slice(0,4),summary=[report.drives?`${report.drives} donor drive${report.drives===1?"":"s"}`:"",report.rested?`${report.rested} recovery day${report.rested===1?"":"s"}`:"",report.tours?`${report.tours} field tour${report.tours===1?"":"s"}`:""].filter(Boolean).join(" · ")||"The campaign kept moving.",modal=document.createElement("div");modal.className="decision-modal campaign-clock-modal";modal.innerHTML=`<div class="campaign-clock"><div class="clock-montage"><small>${report.passed>1?"DAYS MOVE":"NEXT DAY"}</small><strong>${fmt(report.start)}</strong><i aria-hidden="true">→</i><strong>${fmt(report.end)}</strong><span class="clock-days">+${report.passed} DAY${report.passed===1?"":"S"}</span></div><article class="field-edition"><div class="paper-masthead"><span>REPUBLIC 543</span><b>FIELD EDITION</b><span>${fmt(report.end)}</span></div><div class="paper-lead"><small>CAMPAIGN DESK</small><h2>${safe(report.reason||"The week closes. The next move is yours.")}</h2><p>${safe(summary)}${report.raised?` · ₹${money(report.raised)} raised from disclosed donors.`:""}</p></div><div class="paper-headlines">${headlines.map((h,i)=>`<div><b>${i===0?"LEAD":"BRIEF"}</b><strong>${safe(h.title)}</strong><span>${safe(h.detail)}</span></div>`).join("")||"<p>No field report was filed.</p>"}</div><button type="button" class="dispatch-action clock-continue">Read the field →</button></article></div>`;document.body.appendChild(modal);const close=modal.querySelector?.(".clock-continue");if(close)close.onclick=()=>modal.remove();}
if(typeof document!=="undefined"&&document.addEventListener)document.addEventListener("toggle",e=>{if(e.target?.classList?.contains("routine-details")&&state.player){state.ui={...(state.ui||{}),routineOpen:e.target.open};}},true);
/* Decision rooms never stack: a revision replaces the previous step instead of trapping focus behind it. */
if(typeof MutationObserver!=="undefined"&&typeof document!=="undefined"&&document.body)new MutationObserver(records=>{for(const r of records)for(const n of r.addedNodes)if(n.classList?.contains("decision-modal"))document.querySelectorAll(".decision-modal").forEach(m=>{if(m!==n)m.remove();});}).observe(document.body,{childList:true});
